def _validate_workers(workers: list[dict]) -> None:
    if not isinstance(workers, list):
        raise TypeError(f"workers must be a list, got {type(workers).__name__}")
    for i, w in enumerate(workers):
        if not isinstance(w, dict):
            raise TypeError(f"workers[{i}] must be a dict, got {type(w).__name__}")
        if "name" not in w:
            raise ValueError(f"workers[{i}] is missing required 'name' field")
        if not isinstance(w["name"], str):
            raise TypeError(
                f"workers[{i}]['name'] must be a str, got {type(w['name']).__name__}"
            )
        if "enabled" in w and not isinstance(w["enabled"], bool):
            raise TypeError(
                f"workers[{i}]['enabled'] must be a bool, got {type(w['enabled']).__name__}"
            )


def _validate_jobs(jobs: list[str]) -> None:
    if not isinstance(jobs, list):
        raise TypeError(f"jobs must be a list, got {type(jobs).__name__}")
    for i, j in enumerate(jobs):
        if not isinstance(j, str):
            raise TypeError(f"jobs[{i}] must be a str, got {type(j).__name__}")


def _validate_capacities(capacities: dict[str, int] | None) -> None:
    if capacities is None:
        return
    if not isinstance(capacities, dict):
        raise TypeError(
            f"capacities must be a dict or None, got {type(capacities).__name__}"
        )
    for key, val in capacities.items():
        if not isinstance(key, str):
            raise TypeError(
                f"capacities key {key!r} must be a str, got {type(key).__name__}"
            )
        if not isinstance(val, int) or isinstance(val, bool):
            raise TypeError(
                f"capacities[{key!r}] must be an int, got {type(val).__name__}"
            )
        if val < 0:
            raise ValueError(f"capacities[{key!r}] must be non-negative, got {val}")


